  'Confirm with a passkey': 'Mit einem Passkey bestätigen',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'Bestätigt. Erstelle jetzt den neuen Passkey; dein Browser fragt, wo er gespeichert werden soll.',
  'Copy link': 'Link kopieren',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Erstelle auf diesem Gerät einen Passkey für das Profil „{0}“. Damit meldest du dich hier ab jetzt an.',
  'Enter the code from your other device.': 'Gib den Code von deinem anderen Gerät ein.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Für dieses Gerät, einen Sicherheitsschlüssel, einen Passwort-Manager oder dein Handy über den QR-Code des Browsers. Bestätige zuerst, dass du es bist.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Mit ihm kann sich niemand mehr bei diesem Profil anmelden. Ein Gerät, das damit schon angemeldet ist, bleibt angemeldet. Falls es verloren gegangen ist, nutze „Überall abmelden“.',
  'It is your only way in, so it cannot be removed until there is another.': 'Er ist dein einziger Weg ins Profil und lässt sich deshalb erst entfernen, wenn es einen weiteren gibt.',
