  'You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.': 'Du bekommst einen Code, mit dem dein Handy oder ein anderer Computer einen Passkey für dieses Profil erstellen kann. Bestätige zuerst, dass du es bist.',
