  'Before the Coach starts': 'Bevor der Coach loslegt',
  'When you ask for a plan or a review, this instance sends the following to {0}, running on this server under the instance owner’s account.': 'Wenn du einen Plan oder eine Auswertung anforderst, sendet diese Instanz Folgendes an {0}, das auf diesem Server unter dem Konto des Betreibers läuft.',
  'the configured AI provider': 'den eingerichteten KI-Anbieter',
  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'Dein Name, deine Anmeldedaten und alles andere zu deinem Konto bleiben hier. Daten anderer Personen sind nie dabei.',
  'You can turn this off at any time, which also discards anything the Coach is holding for you.': 'Du kannst das jederzeit abschalten; damit wird auch alles verworfen, was der Coach für dich vorhält.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'Der Coach ist weder Arzt noch Physiotherapeut. Wenn etwas wehtut, frag eine Fachkraft.',
  'Not now': 'Jetzt nicht',
  'Meet the Coach': 'Lerne den Coach kennen',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs on this server, it never changes anything without your say-so, and it is off until you turn it on.': 'Ein KI-Coach, der deinen Plan entwirft und ihn an das anpasst, was du tatsächlich protokollierst. Er läuft auf diesem Server, ändert nie etwas ohne dein Einverständnis und ist aus, bis du ihn einschaltest.',
