  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Der Coach passt das Volumen an die Zeit an, die du wirklich hast, inklusive Pausen zwischen den Sätzen.',
  'What can you train with?': 'Womit kannst du trainieren?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Wähle alles aus, worauf du Zugriff hast. Lässt du es leer, nutzt der Coach die ganze Bibliothek.',
  'Anything to work around?': 'Gibt es etwas zu berücksichtigen?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Verletzungen, Gelenke, die zicken, Bewegungen, die nicht gehen, oder praktische Grenzen wie Training um 6 Uhr in einer Wohnung.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'z. B. „empfindliche linke Schulter, kein Schulterdrücken mit der Langhantel“',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Wenn etwas wirklich wehtut, geh zu einer Fachkraft. Der Coach plant vorsichtig, kann aber nichts diagnostizieren.',
