  'Sets the pace of progression, and how much the Coach assumes you know.': 'Bestimmt das Tempo der Progression und wie viel der Coach voraussetzt.',
  'Suggestions': 'Vorschläge',
  'Tell the Coach what to change…': 'Sag dem Coach, was sich ändern soll…',
  'The Coach builds the whole plan around this.': 'Darum herum baut der Coach den ganzen Plan.',
  'This usually takes a minute or two.': 'Das dauert meist ein bis zwei Minuten.',
  'Got it. I won’t suggest these again without new evidence.': 'Verstanden. Ohne neue Hinweise schlage ich das nicht wieder vor.',
  'Usually about {0} min.': 'Dauert meist etwa {0} Min.',
