  'Top sets logged without an effort rating; add RIR so the next review can read how hard they were.': 'Top-Sätze ohne Anstrengungs-Bewertung geloggt; ergänze RIR, damit die nächste Überprüfung sehen kann, wie hart sie waren.',
  'Add the next load step on the main lift.': 'Beim Hauptlift die nächste Gewichtsstufe drauflegen.',
  'Repeat the same loads and get every set.': 'Dieselben Gewichte wiederholen und jeden Satz schaffen.',
  'Keep the session under an hour and a quarter.': 'Die Einheit unter eineinviertel Stunden halten.',
  'A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.': 'Eine saubere Einheit: alles auf dem Zettel erledigt und die Gewichte haben gehalten. Genau so sieht Fortschritt von innen aus: unspektakulär, wiederholt.',
  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': 'Der Großteil der Arbeit ist erledigt. Ein oder zwei Sätze blieben kurz, das ist einmal völlig okay. Ein Signal wird es erst, wenn dieselben Sätze beim nächsten Mal wieder fehlen.',
