  'Your server’s address answered with something other than Gains (HTTP {0}). Your changes are kept here.': 'Die Adresse deines Servers hat mit etwas anderem als Gains geantwortet (HTTP {0}). Deine Änderungen bleiben hier.',
  'Server error (HTTP {0})': 'Serverfehler (HTTP {0})',
