  'Your server no longer accepts this browser. Your changes are kept here.': 'Dein Server akzeptiert diesen Browser nicht mehr. Deine Änderungen bleiben hier.',
  'This phone is no longer paired with your server. Your changes are kept here.': 'Dieses Handy ist nicht mehr mit deinem Server gekoppelt. Deine Änderungen bleiben hier.',
  'The server refuses this phone': 'Der Server lehnt dieses Handy ab',
  'Your server no longer accepts this phone. Your changes are kept here.': 'Dein Server akzeptiert dieses Handy nicht mehr. Deine Änderungen bleiben hier.',
