  'Couldn’t keep a copy of the changes on this device. Nothing was removed.': 'Die Änderungen konnten nicht auf diesem Gerät aufbewahrt werden. Es wurde nichts entfernt.',
  'Not everything is on your server yet': 'Noch ist nicht alles auf deinem Server',
  'Not on your server yet: {0}': 'Noch nicht auf deinem Server: {0}',
  'Some changes on this device have not reached your server.': 'Einige Änderungen auf diesem Gerät haben deinen Server noch nicht erreicht.',
  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Versuch es noch einmal oder exportiere zuerst ein Backup. Machst du trotzdem weiter, bleibt eine Kopie dieser Änderungen auf diesem Gerät, bis es sich wieder mit diesem Konto mit diesem Server verbindet. Dann werden sie wieder hinzugefügt.',
  'Syncing…': 'Wird synchronisiert…',
  'Try again': 'Erneut versuchen',
  'Last synced: {0}': 'Zuletzt synchronisiert: {0}',
  'Not synced with this server yet': 'Noch nicht mit diesem Server synchronisiert',
  'Server & sync': 'Server & Sync',
  'Signed in as {0}': 'Angemeldet als {0}',
  'Sync now': 'Jetzt synchronisieren',
  'Your changes are kept here, and merged into your account once it is paired again.': 'Deine Änderungen bleiben hier und werden in dein Konto übernommen, sobald das Handy neu gekoppelt ist.',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'Deine Änderungen bleiben hier und werden in dein Konto übernommen, sobald du wieder angemeldet bist.',
  'Changes kept for {0}': 'Aufbewahrte Änderungen für {0}',
  'Added back when this device connects as that account again.': 'Werden wieder hinzugefügt, wenn sich dieses Gerät wieder mit diesem Konto verbindet.',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': 'Die Änderungen, die dein Server noch nicht hat, bleiben auf diesem Gerät und werden wieder hinzugefügt, wenn es sich wieder mit diesem Konto verbindet.',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': 'Dieses Handy wechselt zurück in den lokalen Modus, und die Kopie deines Kontos wird davon entfernt. Vorher wird geprüft, ob dein Server jede Änderung hat. Falls nicht, entscheidest du, was mit ihnen passiert.',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': 'Deine Daten werden aus diesem Browser entfernt; dein Profil auf dem Server behält sie. Vorher wird geprüft, ob der Server jede Änderung hat. Falls nicht, entscheidest du, was mit ihnen passiert.',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': 'Meldet dieses Profil auf allen Geräten ab, auch auf diesem. Damit gekoppelte Handys werden getrennt und müssen neu gekoppelt werden. Deine Passkeys funktionieren weiter, du kannst dich also jederzeit wieder damit anmelden.',
  '{0} change': '{0} Änderung',
