  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'Zu jedem Drücken ein Ziehen, damit die Schultern im Gleichgewicht bleiben.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Eine Zwei-Tage-Rotation auf drei Einheiten pro Woche, aufgebaut auf der Ausrüstung, die du angegeben hast. Grundübungen zuerst, zu jedem Drücken ein Ziehen und genug Überschneidung zwischen den Tagen, dass nichts zwei Wochen lang untrainiert bleibt.',
  'Based on the training already in this demo profile.': 'Auf Grundlage des Trainings, das schon in diesem Demo-Profil steht.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Das Körpergewicht stagniert seit vier Wochen, obwohl das Ziel Zunehmen ist. Das ist ein Küchenproblem, kein Trainingsproblem. Am Plan liegt es nicht.',
  'Demo': 'Demo',
  'Demo data reset': 'Demo-Daten zurückgesetzt',
  'Direct arm work, since you asked for it.': 'Direkte Armarbeit, weil du dir das gewünscht hast.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Jeder Top-Satz dieser Übung lag drei Einheiten lang bei RPE 9,5 oder höher, und das Gewicht hat sich nicht bewegt. Die Bewegung für vier Wochen zu tauschen, löst so ein Plateau meist schneller, als sich an derselben festzubeißen.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Beispieldaten, nur in diesem Browser gespeichert. Tob dich aus und ändere, was du willst.',
  'Full body A': 'Ganzkörper A',
  'Full body B': 'Ganzkörper B',
  'Horizontal pressing, the other half of the session.': 'Horizontales Drücken, die andere Hälfte der Einheit.',
  'Live demo. Everything stays in this browser.': 'Live-Demo. Alles bleibt in diesem Browser.',
  'No training history yet, so starting conservatively.': 'Noch kein Trainingsverlauf, also ein vorsichtiger Einstieg.',
  'Passkey sign-in, sync across your devices, your own data.': 'Anmeldung per Passkey, Sync zwischen deinen Geräten, deine eigenen Daten.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Setzt Beispielplan, Trainings und Wiegungen auf den Anfangsstand zurück.',
  'Reset': 'Zurücksetzen',
  'Reset demo data': 'Demo-Daten zurücksetzen',
  'Reset demo data?': 'Demo-Daten zurücksetzen?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Überarbeitet, wie gewünscht. Alles, was du nicht infrage gestellt hast, ist genau wie vorher.',
  'Same pattern, higher reps than day A.': 'Gleiches Bewegungsmuster, mehr Wiederholungen als an Tag A.',
  'Self-host it in a minute →': 'In einer Minute selbst hosten →',
  'Self-host Gains': 'Gains selbst hosten',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Die Einheiten dauern rund fünfzehn Minuten länger als geplant. Diese Zusatzübung verliert am wenigsten, wenn ein Satz wegfällt.',
  'Start the demo': 'Demo starten',
  'The main lower-body driver, where most of the strength comes from.': 'Der Hauptantrieb für den Unterkörper, hier kommt der Großteil der Kraft her.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Dieselben Bewegungsmuster, andere Varianten: genug Überschneidung für Fortschritt, genug Abwechslung, damit es frisch bleibt.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Die zwei großen Muster für Unterkörper und Drücken zuerst, solange du frisch bist.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the Gains server, which you get by self-hosting it.': 'Diese Demo läuft komplett in deinem Browser mit Beispieldaten. Nichts wird irgendwohin gesendet. Anmeldung per Passkey und Sync zwischen deinen Geräten gibt es mit dem Gains-Server, den du bekommst, indem du ihn selbst hostest.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Drei Dinge, die sich zu ändern lohnen, und eines, das man wissen sollte. Alles andere funktioniert: Kniebeuge und Zugübungen machen beide planmäßig Fortschritte.',
  'Vertical pressing.': 'Vertikales Drücken.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Du hast diese Einheit drei Wochen in Folge auf Samstag verschoben. Besser, der Plan sagt das, als dass du ihn jedes Mal übergehst.',
  'You’re in the demo': 'Du bist in der Demo',
